import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const u=JSON.parse('{"title":"第58章 两个号","description":"","frontmatter":{},"headers":[],"relativePath":"第58章_两个号.md","filePath":"第58章_两个号.md"}'),o={name:"第58章_两个号.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第58章-两个号" tabindex="-1">第58章 两个号 <a class="header-anchor" href="#第58章-两个号" aria-label="Permalink to &quot;第58章 两个号&quot;">​</a></h1><p>十月我把她那两个号的事，第一次弄清楚了。</p><p>以前我不清楚。我只知道&quot;她现在用这个号跟我说话&quot;。</p><p>那天她跟我讲了很久，讲完我才把这件事画下来。</p><p>一个是她真正的号。头像是一只猫，朋友圈对她妈开放，对她爸也开放。</p><p>那个号上，她妈每周发一条。</p><p>发的是风景。</p><p>我看过她截给我的图。一张海，一张教堂，一张超市里堆成山的橙子。</p><p>配的文字从来是同一句：一切都好，放心。</p><p>我说，这是你妈发的？</p><p>她说，是我发的。</p><p>我说，那你为什么说是你妈。</p><p>她说，因为这个号上的东西，不是给我看的。</p><p>她说，是给我妈拿去发给别人看的。</p><p>她说，她每周要截一次图，发到她那边的亲戚群里。</p><p>她说，我少发一张，她就要问。</p><p>她说，所以我发海，发橙子。</p><p>她说，我发橙子是因为橙子不会说出我在哪儿。</p><p>我坐在桌前，看着这几行。</p><p>我说，那你在那个号上，还发你自己的生活吗。</p><p>她说，发过。</p><p>她说，大一上学期我发过一次我煮糊的东西。</p><p>我说，然后呢。</p><p>她说，然后第二天我姨打电话问我妈，她是不是吃得不好。</p><p>她说，我妈在电话里&quot;哎哟&quot;了一声。</p><p>她说，那一声我听见了。</p><p>她说，从那以后我在那个号上只发橙子和海。</p><p>另一个号，是她自己弄的那个。</p><p>头像是空的。名字是她自己取的。</p><p>那个号上没有亲戚。</p><p>那个号上她发什么？</p><p>她发一些她不敢说成是她的东西。</p><p>她发一个空房间，窗帘被吹起来。她发一句很难听的歌词。她发一段话，发完三分钟删掉。</p><p>她说，这个号是给我自己用的。</p><p>她说，你只是恰好在我愿意给你看的时候，把它发给了你。</p><p>我说，那你不愿意的时候呢。</p><p>她说，我就发完删。</p><p>我说，你删了我看得见。</p><p>她说，你看不见。</p><p>她说，你只是看见过一次。</p><p>我说，我数过。</p><p>她说，你数这个干什么。</p><p>我说，我数出来一个月你删了十一次。</p><p>她没回。</p><p>过了一会儿她回了一句。</p><p>她说，你别把这个也抄下来。</p><p>我说，我已经抄了。</p><p>她说，你抄下来，它就不干净了。</p><p>她说，我删是因为我想让它没有发生过。</p><p>她说，你一抄，它又活了。</p><p>我看这一段，看了很久。</p><p>我打了一句话：那我不抄。</p><p>打完我把这句删了。</p><p>我发的是：好。</p><p>那天夜里她把两个号的事，最后总结了一遍。</p><p>她说，我跟你说清楚一件事。</p><p>我说，你说。</p><p>她说，以后我在那个号上说的，都是给我妈看的。</p><p>她说，在这个号上说的，才是我的。</p><p>她说，这个号上我说什么，你都不许往那个号上引。</p><p>我说，明白。</p><p>她说，还有。</p><p>她说，如果有一天这个号也变成给别人看的，你就当我什么都没说。</p><p>我说，什么时候会变。</p><p>她说，我妈要是哪天知道我还有这个号。</p><p>她说完这句，隔了一会儿，又补了一句。</p><p>她说，所以你不要太依赖这个号。</p><p>她说，它不是一个地方，它是一段时间。</p><p>我把这一句在本子上抄了。</p><p>抄完我把它画了一个圈。</p><p>那天以后，她旧号上每周那张图，我开始认真看。</p><p>我看海是哪一种海，看橙子是怎么堆的。</p><p>我知道那不是她。</p><p>可是我发现，我看那些图的时候，心里会松一下。</p><p>因为我妈拿着我的照片发给她妈看的时候，也是这么干的。</p><p>我妈把我小学的一张奖状拍了照，发给她姨。那张奖状上写的是另一个名字。</p><p>因为我改名那年，奖状没换。</p><p>这件事我跟她讲过。</p><p>她听完说了一句：你看，我们两家是一个做法。</p><p>后来出了一件事，才让我真正明白这两个号有多危险。</p><p>十一月，她旧号上发了一张橙子。</p><p>我那时候不知道那张图已经发出去多久了。我只看见她家一个阿姨在下面评论，问她甜不甜。</p><p>我手欠，我在下面留了一句：那边橙子便宜。</p><p>发完两个小时，这个号上弹进来一条。</p><p>她说，你刚才在干什么。</p><p>我说，我在你那个号上回了一句。</p><p>她说，我知道！</p><p>她说，那条是我妈回的！</p><p>我说，啊。</p><p>她说，她看见你了。</p><p>她说，她现在问我那个号上这个人是谁。</p><p>我说，那你说什么。</p><p>她不说话。</p><p>过了大概三分钟，她说，我说是同学。</p><p>我说，然后呢。</p><p>她说，然后她把我手机拿走了。</p><p>我说，对不起。</p><p>她说，你现在说对不起有什么用。</p><p>她说，我跟你说过八百遍，那个号不是我。</p><p>那一下我什么都说不出来。</p><p>因为她讲的是对的。</p><p>我在那个号上留的那六个字，在她那边是一个具体的代价：她一个晚上手机不在手上。</p><p>我说，那我以后那个号上看都不看。</p><p>她说，你别这么说。</p><p>我说，那你说怎么办。</p><p>她说，你就当那个号上没有人。</p><p>她说，包括我。</p><p>第二件事，是她把两个号弄重了一次。</p><p>十二月初，她旧号上忽然发了一段话。</p><p>那段话我认得。</p><p>因为三天前，她在那个号上发过一模一样的。</p><p>一个字都不差。</p><p>她一定是复制错了粘贴板。</p><p>我看到那段话的时候，手里拿着一个牙刷，站在卫生间里。</p><p>我第一反应是提醒她。</p><p>我把手机拿起来，打到一半，停了。</p><p>因为我忽然想明白：我要是提醒她，我就得告诉她，我一直在看她那个号。</p><p>而那个号是她妈的号。</p><p>我把那半句话删了。</p><p>我什么都没发。</p><p>第二天她自己在新的号上发了一句：我昨天好像发错地方了。</p><p>我说，没有。</p><p>她说，你怎么知道没有。</p><p>我说，因为你要是发了，你现在不会这么平静。</p><p>她说，哦。</p><p>那天晚上我在本子上抄下这件事的时候，手是抖的。</p><p>我撒了一个很精密的谎。</p><p>精密到我自己都看不出破绽。</p><p>我保护了她的安全。</p><p>我也保住了我能看她那个号的权利。</p><p>这两件事我一件也没告诉她。</p><p>那晚十一点，我下线以前，她在另一个号上发了一句。</p><p>她说，你现在是我这边唯一知道有两个我的人。</p><p>我说，嗯。</p><p>她说，你别把这个当成一件好事。</p><p>我说，我知道。</p><p>她说，你知道什么。</p><p>我说，这不算信任，这算同谋。</p><p>她隔了很久。</p><p>她说，你终于说一句不长脑子的话了。</p><p>我说，我说的错了？</p><p>她说，不错。</p><p>她说，所以你别说第二次。</p>',143)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
